import type { GeneratedManifest, GeneratedOption } from './types.js';
import { publicOptions, rootFamilies } from './load-command-model.js';

const GENERATED_WARNING =
  '<!-- Generated by `pnpm skills:vercel-cli:generate`. Do not edit by hand. -->';

function formatOptionType(option: GeneratedOption): string {
  if (Array.isArray(option.type)) {
    return `list<${option.type.join('|')}>`;
  }
  return option.type;
}

function formatOptionLine(option: GeneratedOption): string {
  const shorthand = option.shorthand ? `\`-${option.shorthand}\`, ` : '';
  const arg = option.argument ? ` <${option.argument}>` : '';
  return `- ${shorthand}\`--${option.name}${arg}\` (${formatOptionType(option)}) — ${option.description}`;
}

/** First sentence of a description, for compact index tables. */
export function firstSentence(text: string): string {
  const normalized = text.replace(/\s+/g, ' ').trim();
  const match = normalized.match(/^.*?[.!?](?=\s)/);
  if (!match) {
    return normalized;
  }
  return `${match[0]} …`;
}

/**
 * The command map: every visible root family with aliases and a one-line
 * description, plus global options. Exact per-command syntax is deliberately
 * NOT generated — the installed CLI's `--help` is the syntax authority.
 */
export function renderIndex(manifest: GeneratedManifest): string {
  const roots = rootFamilies(manifest.commands)
    .slice()
    .sort((a, b) => a.name.localeCompare(b.name));
  const lines: string[] = [
    GENERATED_WARNING,
    '',
    '# Vercel CLI command map (generated)',
    '',
    'Discovery only: which commands exist, their aliases, and the global options.',
    'This map is built from command registration metadata, unlike the CLI’s hand-maintained root help text, so it cannot list commands that do not exist.',
    'For exact syntax (arguments, options, examples), run `vercel <command> --help` — the installed CLI is the syntax authority and is always version-correct.',
    '',
    '## Root command families',
    '',
    '| Command | Aliases | Description |',
    '| --- | --- | --- |',
  ];

  for (const root of roots) {
    const aliases =
      root.aliases.length > 0
        ? root.aliases.map(a => `\`${a}\``).join(', ')
        : '—';
    const desc = firstSentence(root.description)
      .replace(/\|/g, '\\|')
      .replace(/\n/g, ' ');
    lines.push(`| \`${root.name}\` | ${aliases} | ${desc} |`);
  }

  lines.push('');
  lines.push('## Global options');
  lines.push('');
  lines.push(
    'Accepted by every command, except where a command’s own `--help` says otherwise.'
  );
  lines.push('');
  for (const option of publicOptions(manifest.globalOptions)) {
    lines.push(formatOptionLine(option));
  }
  lines.push('');

  return `${lines.join('\n').trimEnd()}\n`;
}

/** Reject generator-injected timestamps; CLI example ISO dates are allowed. */
const GENERATED_TIMESTAMP_RE =
  /"generatedAt"\s*:|Generated at\b|\bgenerated_at\b/i;

export function assertGeneratedContentSafe(
  content: string,
  forbiddenSubstrings: string[]
): void {
  if (GENERATED_TIMESTAMP_RE.test(content)) {
    throw new Error('Generated index contains a generator timestamp field');
  }
  for (const forbidden of forbiddenSubstrings) {
    if (forbidden && content.includes(forbidden)) {
      throw new Error(
        `Generated index contains forbidden path substring: ${forbidden}`
      );
    }
  }
}
